<script setup>const p=defineProps({modelValue:String,label:{default:'¿Qué versión cabe hoy?'},levels:{default:()=>[{value:'minimal',label:'Mínima',help:'Lo más pequeño que cuenta',color:'var(--progress-adapted)'},{value:'usual',label:'Habitual',help:'Como lo planeaste',color:'var(--action-primary)'},{value:'extra',label:'De sobra',help:'Si hoy hay energía',color:'var(--accent-focus)'}]}});defineEmits(['update:modelValue'])</script><template><fieldset><legend>{{label}}</legend><button v-for="l in p.levels" :key="l.value" type="button" :class="{on:modelValue===l.value}" :style="{'--c':l.color}" @click="$emit('update:modelValue',l.value)"><i/><span><b>{{l.label}}</b><small>{{l.help}}</small></span></button></fieldset></template><style scoped>fieldset{display:grid;gap:8px;margin:0;padding:0;border:0}legend{margin-bottom:4px;color:var(--text-primary);font:600 15px var(--font-core)}button{display:flex;align-items:center;gap:12px;min-height:58px;padding:10px 14px;text-align:left;border:1px solid var(--border-subtle);border-radius:var(--radius-md);background:var(--surface-primary);color:var(--text-primary)}button.on{border-color:var(--c);background:color-mix(in srgb,var(--c) 10%,var(--surface-primary))}i{width:12px;height:12px;border:2px solid var(--c);border-radius:50%}.on i{background:var(--c);box-shadow:inset 0 0 0 2px var(--surface-primary)}b,small{display:block;font-family:var(--font-core)}small{margin-top:3px;color:var(--text-muted)}</style>
